/* lookup(word, lang) -> bool · האם המחרוזת המנורמלת היא מילה אמיתית של השפה
 * שאינה צורה קבילה של אף ערך במאגר. נבנה על ידי typo-lab/build_runtime_lexicon.js ·
 * אל תערוך ביד. ההנמקה, גבול הרישיון וההנמקה ל-FPR נמצאים בראש הבנאי.
 *
 * ⛔ רישיון · המקורות הם טקסטים שנכתבו בפרויקט הזה בלבד. אין כאן שום מילון חיצוני.
 *   מודרים במפורש: דוחות/מאגר-נקי/01-גלם.tsv · דוחות/מאגר-נקי/19-צירופים-מהרשת.tsv ·
 *   pipeline_output/*.json · שלושתם רשימות שהמקור החיצוני בחר את תוכנן.
 *
 * ⚠ המבנה הוא מסנן Bloom · positive שגוי אפשרי ומחירו recall (דחיית שגיאת כתיב
 *   אמיתית), ‏negative שגוי בלתי אפשרי מבנית. הקלט חייב להיות **מנורמל כבר**
 *   (norm לעברית, normEn לאנגלית), מילה אחת בלי רווחים.
 */
(function (root) {
  'use strict';

  var TL = {
    "version": "typo-lab/runtime-lexicon/v1",
    "fprTarget": 0.005,
    "he": {
      "n": 29296,
      "m": 323072,
      "k": 8,
      "bytes": 40384,
      "min": 2,
      "b64": ""
    },
    "en": {
      "n": 5928,
      "m": 65376,
      "k": 8,
      "bytes": 8172,
      "min": 2,
      "b64": ""
    }
  };

  TL.he.b64 = "";
  TL.en.b64 = "";

  function TL_b64(s) {
    if (typeof atob === 'function') {
      var bin = atob(s), a = new Uint8Array(bin.length), i;
      for (i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i);
      return a;
    }
    var b = Buffer.from(s, 'base64');
    return new Uint8Array(b.buffer, b.byteOffset, b.byteLength);
  }

  function TL_hash(str, seed) {
    var s = String(str);
    var h = seed >>> 0;
    for (var i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 0x01000193) >>> 0;
    }
    h ^= h >>> 16;
    h = Math.imul(h, 0x85ebca6b) >>> 0;
    h ^= h >>> 13;
    h = Math.imul(h, 0xc2b2ae35) >>> 0;
    h ^= h >>> 16;
    return h >>> 0;
  }

  function TL_idx(word, lang, m, k, out) {
    var key = lang + '' + word;
    var h1 = TL_hash(key, 0x811c9dc5);
    var h2 = (TL_hash(key, 0x9e3779b1) | 1) >>> 0;
    for (var i = 0; i < k; i++) out[i] = (h1 + i * h2) % m;
    return out;
  }

  var BITS = { he: null, en: null };
  var SCRATCH = [];

  function lookup(word, lang) {
    var L = lang === 'en' ? 'en' : 'he';
    var cfg = TL[L];
    if (!word || word.length < cfg.min) return false;
    var bits = BITS[L] || (BITS[L] = TL_b64(cfg.b64));
    TL_idx(word, L, cfg.m, cfg.k, SCRATCH);
    for (var i = 0; i < cfg.k; i++) {
      var p = SCRATCH[i];
      if (!(bits[p >>> 3] & (1 << (p & 7)))) return false;
    }
    return true;
  }

  TL.lookup = lookup;
  TL.has = lookup;
  root.TYPO_LEX = TL;
  /* אותו אובייקט בדיוק גם ל-require של המעבדה · השער מאמת שהחיפוש שנמדד כאן
     הוא החיפוש שרץ בדפדפן, ולא מימוש מקביל שנכתב פעמיים. */
  if (typeof module === 'object' && module.exports) module.exports = TL;
})(typeof window !== 'undefined' ? window : (typeof globalThis !== 'undefined' ? globalThis : this));
